import "server-only";
import type { Offer, RetailerId } from "../types";
import entries from "./catalog.json";

type CatalogEntry = {
  kind: string;
  retailer: RetailerId;
  brand: string;
  title: string;
  price: number | null;
  imageUrl: string;
  url: string;
  tier: "budget" | "mid" | "premium";
  checkedAt: string;
};

const CATALOG = entries as CatalogEntry[];
const KINDS = [...new Set(CATALOG.map((e) => e.kind))];

function words(text: string) {
  return text
    .toLowerCase()
    .split(/[^a-z]+/)
    .filter((w) => w.length > 2)
    .map((w) => w.replace(/(es|s)$/, ""));
}

/** The catalog kind whose words best cover the query, e.g. "organic zip swaddle" → "zip swaddle newborn". */
function matchKind(query: string) {
  const queryWords = new Set(words(query));
  let best: { kind: string; score: number } | null = null;
  for (const kind of KINDS) {
    const kindWords = words(kind);
    const hits = kindWords.filter((w) => queryWords.has(w)).length;
    // Reward covering the query, not just the kind, so "crib mattress" beats "crib".
    const score = hits / kindWords.length + hits / Math.max(queryWords.size, 1);
    if (hits && (!best || score > best.score)) best = { kind, score };
  }
  return best && best.score >= 0.8 ? best.kind : null;
}

function toOffer(entry: CatalogEntry): Offer {
  return {
    retailer: entry.retailer,
    externalId: `catalog:${entry.url}`,
    title: entry.title,
    price: entry.price,
    imageUrl: entry.imageUrl,
    url: entry.url,
    rating: entry.tier === "budget" ? 4.2 : 4.5,
    inStock: true,
  };
}

/** Real, hand-checked products for a query, or null when the catalog doesn't cover it. */
export function catalogSearch(query: string, maxPrice?: number): Offer[] | null {
  const kind = matchKind(query);
  if (!kind) return null;
  const matches = CATALOG.filter((e) => e.kind === kind);
  const affordable = maxPrice ? matches.filter((e) => e.price === null || e.price <= maxPrice) : matches;
  const pool = affordable.length ? affordable : matches;
  const wantsBudget = /\b(affordable|cheap|budget)\b/i.test(query);
  return pool
    .toSorted((a, b) => Number(wantsBudget && b.tier === "budget") - Number(wantsBudget && a.tier === "budget"))
    .map(toOffer);
}

import type { Offer, RetailerId } from "../types";
import { RETAILER_LABELS } from "../types";

const SEARCH_URLS: Record<RetailerId, (q: string) => string> = {
  amazon: (q) => `https://www.amazon.com/s?k=${encodeURIComponent(q)}`,
  walmart: (q) => `https://www.walmart.com/search?q=${encodeURIComponent(q)}`,
  target: (q) => `https://www.target.com/s?searchTerm=${encodeURIComponent(q)}`,
};

/** An honest fallback when we have no real product: a link to the store's own search. */
export function searchLinkOffer(retailer: RetailerId, query: string): Offer {
  return {
    retailer,
    externalId: `search:${retailer}:${query.toLowerCase()}`,
    title: `Search ${RETAILER_LABELS[retailer]} for “${query}”`,
    price: null,
    imageUrl: null,
    url: SEARCH_URLS[retailer](query),
    rating: null,
    inStock: true,
  };
}

