"use client";

import Link from "next/link";
import { use, useMemo, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ItemCard } from "@/components/ItemCard";
import { Status } from "@/components/Status";
import { useRegistry } from "@/components/useRegistry";
import { CATEGORIES, type Category } from "@/lib/types";

export default function ReviewPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Review id={id} />
    </AuthGate>
  );
}

type Group = { category: Category; items: unknown[]; pending: Array<{ id: string }> };

function Review({ id }: { id: string }) {
  const { registry, error, setStatus, setPrimary } = useRegistry(id);
  const [category, setCategory] = useState<Category | null>(null);

  const groups = useMemo(() => {
    if (!registry) return [];
    return CATEGORIES.map((c) => {
      const items = registry.items.filter((i) => i.category === c);
      return { category: c, items, pending: items.filter((i) => i.status === "pending") };
    }).filter((g) => g.items.length > 0);
  }, [registry]);

  if (error && !registry) return <Status tone="error">{error}</Status>;
  if (!registry) return <Status>Opening your registry…</Status>;

  const total = registry.items.length;
  const reviewed = registry.items.filter((i) => i.status !== "pending").length;
  const progress = total ? reviewed / total : 0;
  const active = category ? groups.find((g) => g.category === category) : null;
  const current = active?.pending[0];

  const header = (
    <header className="sticky top-0 z-10 -mx-4 space-y-3 bg-bg px-4 pt-5 pb-4 sm:-mx-6 sm:px-6">
      <div className="flex items-center justify-between text-[13px]">
        {active ? (
          <button onClick={() => setCategory(null)} className="link">
            All categories
          </button>
        ) : (
          <Link href={`/registry/${id}`} className="link">
            Registry overview
          </Link>
        )}
        <span className="text-muted tabular-nums">
          {reviewed} of {total} reviewed
        </span>
      </div>
      <div
        className="h-1 overflow-hidden rounded-full bg-line"
        role="progressbar"
        aria-valuenow={reviewed}
        aria-valuemax={total}
        aria-label="Review progress"
      >
        <div className="h-full rounded-full bg-accent transition-[width] duration-500" style={{ width: `${progress * 100}%` }} />
      </div>
    </header>
  );

  if (active) {
    return (
      <main className="space-y-5">
        {header}
        <div className="flex items-baseline justify-between">
          <h1 className="font-serif text-[21px] font-semibold">{active.category}</h1>
          {current && (
            <span className="text-[13px] text-muted tabular-nums">
              {active.items.length - active.pending.length + 1} of {active.items.length}
            </span>
          )}
        </div>

        {current ? (
          <ItemCard key={current.id} item={current} onChooseOffer={(offerId) => void setPrimary(current.id, offerId)}>
            <div className="grid grid-cols-2 gap-3 pt-2">
              <button className="btn-quiet" onClick={() => void setStatus(current.id, "skip")}>
                Skip
              </button>
              <button className="btn-primary" onClick={() => void setStatus(current.id, "keep")}>
                Keep
              </button>
            </div>
          </ItemCard>
        ) : (
          <div className="space-y-6 pt-10">
            <div className="space-y-2">
              <h2 className="font-serif text-[26px] font-semibold">{active.category} is reviewed.</h2>
              <p className="text-muted">
                You kept {active.items.length - registry.items.filter((i) => i.category === active.category && i.status === "skip").length}{" "}
                of {active.items.length} items.
              </p>
            </div>
            <NextStep groups={groups} onPick={setCategory} id={id} />
          </div>
        )}
      </main>
    );
  }

  return (
    <main className="space-y-6">
      {header}
      <div className="space-y-3">
        <h1 className="font-serif text-[33px] leading-tight font-semibold">{registry.title}</h1>
        <p className="max-w-[60ch] text-muted">
          Your full draft is ready. Go through it one category at a time, in any order. Stop whenever you like, your
          progress is saved.
        </p>
      </div>

      <ul className="border-t border-line">
        {groups.map((g) => {
          const done = g.pending.length === 0;
          const minutes = Math.max(1, Math.round(g.pending.length / 3));
          return (
            <li key={g.category} className="border-b border-line">
              <button
                onClick={() => setCategory(g.category)}
                className="flex w-full items-center justify-between gap-4 py-4 text-left transition-colors hover:text-accent"
              >
                <span className="font-serif text-[21px]">{g.category}</span>
                <span className="text-[13px] text-muted tabular-nums">
                  {done ? "Reviewed" : `${g.pending.length} to review, about ${minutes} min`}
                </span>
              </button>
            </li>
          );
        })}
      </ul>

      {progress === 1 && (
        <Link href={`/registry/${id}`} className="btn-primary w-full">
          See and share your registry
        </Link>
      )}
    </main>
  );
}

function NextStep({ groups, onPick, id }: { groups: Group[]; onPick: (c: Category | null) => void; id: string }) {
  const next = groups.find((g) => g.pending.length > 0);
  if (!next) {
    return (
      <Link href={`/registry/${id}`} className="btn-primary w-full">
        See and share your registry
      </Link>
    );
  }
  return (
    <button className="btn-primary w-full" onClick={() => onPick(next.category)}>
      Review {next.category}
    </button>
  );
}

/** A full-height message for loading and error states. */
export function Status({ children, tone }: { children: React.ReactNode; tone?: "error" }) {
  return (
    <p role={tone === "error" ? "alert" : "status"} className={`py-24 text-center ${tone === "error" ? "text-danger" : "text-muted"}`}>
      {children}
    </p>
  );
}

"use client";

import Link from "next/link";
import { use, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ProductPhoto } from "@/components/ProductPhoto";
import { Status } from "@/components/Status";
import { useRegistry } from "@/components/useRegistry";
import { api, formatPrice, totalPrice } from "@/lib/client";
import { CATEGORIES, RETAILER_LABELS, type EditDiff, type Registry, type RegistryItem } from "@/lib/types";

export default function RegistryPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Overview id={id} />
    </AuthGate>
  );
}

function money(amount: number) {
  return `$${Math.round(amount).toLocaleString()}`;
}

function Overview({ id }: { id: string }) {
  const { registry, error, reload, setStatus } = useRegistry(id);

  if (error && !registry) return <Status tone="error">{error}</Status>;
  if (!registry) return <Status>Opening your registry…</Status>;

  const kept = registry.items.filter((i) => i.status !== "skip");
  const pending = registry.items.filter((i) => i.status === "pending").length;
  const purchased = kept.filter((i) => i.purchased).length;
  const total = kept.reduce((sum, i) => sum + totalPrice(i.offers, i.qty), 0);

  return (
    <>
      <main className="space-y-10 pt-6 pb-40">
        <header className="space-y-3">
          <Link href="/" className="link text-[13px]">
            Calm Registry
          </Link>
          <h1 className="font-serif text-[33px] leading-tight font-semibold">{registry.title}</h1>
          <p className="text-muted">
            {kept.length} items, about {money(total)} in all.{" "}
            {purchased > 0 ? `${purchased} gifted so far.` : "Nothing gifted yet."}
          </p>
        </header>

        {pending > 0 && (
          <div className="flex items-center justify-between gap-4 rounded-xl bg-surface px-5 py-4">
            <p>
              {pending} {pending === 1 ? "item" : "items"} still to review
            </p>
            <Link href={`/registry/${id}/review`} className="btn-primary shrink-0 px-4 py-2.5">
              Continue review
            </Link>
          </div>
        )}

        <ShareRow slug={registry.slug} />

        {CATEGORIES.map((category) => {
          const items = kept.filter((i) => i.category === category);
          if (!items.length) return null;
          const subtotal = items.reduce((sum, i) => sum + totalPrice(i.offers, i.qty), 0);
          return (
            <section key={category} aria-labelledby={`cat-${category}`}>
              <div className="flex items-baseline justify-between border-b border-line pb-3">
                <h2 id={`cat-${category}`} className="font-serif text-[21px] font-semibold">
                  {category}
                </h2>
                <span className="text-[13px] text-muted tabular-nums">
                  {items.length} {items.length === 1 ? "item" : "items"}, {money(subtotal)}
                </span>
              </div>
              <ul>
                {items.map((item) => (
                  <ItemRow key={item.id} item={item} onRemove={() => void setStatus(item.id, "skip")} />
                ))}
              </ul>
            </section>
          );
        })}
      </main>
      <EditBar registry={registry} onApplied={reload} />
    </>
  );
}

function ItemRow({ item, onRemove }: { item: RegistryItem; onRemove: () => void }) {
  const primary = item.offers[0];
  return (
    <li className="flex gap-4 border-b border-line py-4">
      <ProductPhoto offer={primary} label={item.name} className="h-[72px] w-[72px]" />
      <div className="min-w-0 flex-1 space-y-1">
        <div className="flex items-baseline justify-between gap-3">
          <p className="font-semibold">
            {item.name}
            {item.qty > 1 && <span className="font-normal text-muted"> ×{item.qty}</span>}
          </p>
          <p className="shrink-0 tabular-nums">{formatPrice(primary?.price ?? null)}</p>
        </div>
        {primary && (
          <a
            href={primary.url}
            target="_blank"
            rel="noopener noreferrer sponsored"
            className="block truncate text-[13px] text-muted hover:text-text"
          >
            {primary.title}, {RETAILER_LABELS[primary.retailer]}
          </a>
        )}
        <div className="pt-1 text-[13px]">
          {item.purchased ? (
            <span className="rounded-md bg-gift-bg px-2 py-0.5 text-gift">
              Gifted{item.purchased.buyerName ? ` by ${item.purchased.buyerName}` : ""}
            </span>
          ) : (
            <button className="link" onClick={onRemove}>
              Remove
            </button>
          )}
        </div>
      </div>
    </li>
  );
}

function ShareRow({ slug }: { slug: string }) {
  const [copied, setCopied] = useState(false);
  const url = typeof window === "undefined" ? `/r/${slug}` : `${window.location.origin}/r/${slug}`;

  async function share() {
    if (navigator.share) {
      await navigator.share({ title: "Our baby registry", url }).catch(() => undefined);
      return;
    }
    await navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="flex items-center justify-between gap-4">
      <div className="min-w-0">
        <p className="font-semibold">Share with family and friends</p>
        <a href={url} target="_blank" rel="noopener noreferrer" className="block truncate text-[13px] text-muted hover:text-text">
          {url.replace(/^https?:\/\//, "")}
        </a>
      </div>
      <button className="btn-quiet shrink-0 px-4 py-2.5" onClick={() => void share()}>
        {copied ? "Link copied" : "Share link"}
      </button>
    </div>
  );
}

const SUGGESTIONS = ["Make it cheaper", "We already have a crib", "More eco-friendly", "Add a baby swing"];

/** Change the registry by describing it, pinned to the bottom of the screen. */
function EditBar({ registry, onApplied }: { registry: Registry; onApplied: () => Promise<void> }) {
  const [text, setText] = useState("");
  const [diff, setDiff] = useState<EditDiff | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const names = new Map(registry.items.map((i) => [i.id, i.name]));

  async function propose(request: string) {
    if (!request.trim()) return;
    setBusy(true);
    setError("");
    try {
      const { diff } = await api<{ diff: EditDiff }>(`/api/registries/${registry.id}/edit`, {
        method: "POST",
        body: JSON.stringify({ request }),
      });
      setDiff(diff);
    } catch (e) {
      setError(e instanceof Error ? e.message : "That change didn't go through. Try again.");
    } finally {
      setBusy(false);
    }
  }

  async function apply() {
    if (!diff) return;
    setBusy(true);
    try {
      await api(`/api/registries/${registry.id}/edit`, { method: "POST", body: JSON.stringify({ diff }) });
      setDiff(null);
      setText("");
      await onApplied();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That change didn't go through. Try again.");
    } finally {
      setBusy(false);
    }
  }

  const hasChanges = diff && (diff.add.length || diff.remove.length || diff.swap.length);

  return (
    <div className="fixed inset-x-0 bottom-0 z-20 border-t border-line bg-bg/95 backdrop-blur">
      <div className="mx-auto max-w-xl space-y-3 px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-6">
        {diff && (
          <div className="max-h-[45dvh] space-y-3 overflow-y-auto rounded-xl bg-surface p-4">
            <p className="font-serif text-[17px] text-note italic">{diff.summary}</p>
            <ul className="space-y-1 text-[14px]">
              {diff.remove.map((id) => (
                <li key={id}>Remove {names.get(id)}</li>
              ))}
              {diff.add.map((item) => (
                <li key={item.name}>Add {item.name}</li>
              ))}
              {diff.swap.map((s) => (
                <li key={s.id}>Find a different {names.get(s.id)?.toLowerCase()}</li>
              ))}
            </ul>
            <div className="flex gap-2">
              <button className="btn-quiet flex-1 py-2.5" onClick={() => setDiff(null)} disabled={busy}>
                Cancel
              </button>
              {hasChanges ? (
                <button className="btn-primary flex-1 py-2.5" onClick={() => void apply()} disabled={busy}>
                  {busy ? "Applying…" : "Apply changes"}
                </button>
              ) : null}
            </div>
          </div>
        )}
        {!diff && !text && (
          <div className="-mx-4 flex gap-2 overflow-x-auto px-4 sm:-mx-6 sm:px-6">
            {SUGGESTIONS.map((s) => (
              <button
                key={s}
                className="chip shrink-0 py-1.5 text-[13px]"
                disabled={busy}
                onClick={() => {
                  setText(s);
                  void propose(s);
                }}
              >
                {s}
              </button>
            ))}
          </div>
        )}
        {error && (
          <p role="alert" className="text-[13px] text-danger">
            {error}
          </p>
        )}
        <form
          onSubmit={(e) => {
            e.preventDefault();
            void propose(text);
          }}
          className="flex gap-2"
        >
          <label htmlFor="edit-request" className="sr-only">
            Describe a change
          </label>
          <input
            id="edit-request"
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="We're getting a hand-me-down stroller"
            className="field"
          />
          <button className="btn-primary shrink-0" disabled={busy || !text.trim()}>
            {busy && !diff ? "Thinking…" : "Change"}
          </button>
        </form>
      </div>
    </div>
  );
}

